begin;
-- A selected commercial offer never changes. Legal-party reconfirmations and
-- unsigned draft refreshes are new immutable facts, separate from that offer.
create table public.selected_quote_identity_proposals_v1(
 id uuid primary key default extensions.gen_random_uuid(),quote_version_id uuid not null references public.quote_versions(id),
 request_id uuid not null references public.service_requests(id),client_organization_id uuid not null references public.organizations(id),provider_organization_id uuid not null references public.organizations(id),
 context_hash text not null check(context_hash~'^[a-f0-9]{64}$'),client_party jsonb not null,provider_party jsonb not null,
 reason text not null check(length(btrim(reason))between 10 and 1000),proposed_by uuid not null references auth.users(id),proposed_at timestamptz not null default clock_timestamp(),content_hash text not null check(content_hash~'^[a-f0-9]{64}$'));
create index selected_quote_identity_proposals_history_idx on public.selected_quote_identity_proposals_v1(quote_version_id,proposed_at desc,id desc);
create table public.selected_quote_identity_responses_v1(proposal_id uuid primary key references public.selected_quote_identity_proposals_v1(id),decision text not null check(decision in('ACCEPT','DECLINE')),content_hash text not null check(content_hash~'^[a-f0-9]{64}$'),reason text not null check(length(btrim(reason))between 10 and 1000),responded_by uuid not null references auth.users(id),responded_at timestamptz not null default clock_timestamp());
create table public.selected_quote_contract_refreshes_v1(id uuid primary key default extensions.gen_random_uuid(),contract_id uuid not null references public.contracts(id),previous_version_id uuid not null references public.contract_versions(id),contract_version_id uuid not null unique references public.contract_versions(id),identity_reconfirmation_id uuid references public.selected_quote_identity_proposals_v1(id),context_hash text not null check(context_hash~'^[a-f0-9]{64}$'),source_hash text not null check(source_hash~'^[a-f0-9]{64}$'),reason text not null check(length(btrim(reason))between 10 and 1000),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp());
do $$declare t text;begin foreach t in array array['selected_quote_identity_proposals_v1','selected_quote_identity_responses_v1','selected_quote_contract_refreshes_v1']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);execute format('create trigger %I before update or delete on public.%I for each row execute function private.prevent_contract_immutable_change()',t||'_immutable',t);end loop;end$$;
-- No direct table grant: these scoped projections are the only disclosure path.
create function private.selected_quote_identity_context_v1(p_quote_version_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$
declare v public.quote_versions%rowtype;q public.quotes%rowtype;r public.rfqs%rowtype;s public.service_requests%rowtype;d public.quote_selection_decisions%rowtype;client_value jsonb;provider_value jsonb;original jsonb;basis jsonb;blocked text[]:='{}';address_value text;begin
 select*into v from public.quote_versions where id=p_quote_version_id;select*into q from public.quotes where id=v.quote_id;select*into r from public.rfqs where id=q.rfq_id;select*into s from public.service_requests where id=r.request_id;select*into d from public.quote_selection_decisions where rfq_id=r.id;
 if v.id is null or q.status is distinct from'SELECTED'or q.selected_version_id is distinct from v.id or d.selected_quote_version_id is distinct from v.id or d.selected_quote_id is distinct from q.id or r.request_version_id is distinct from s.current_version_id then raise exception'SELECTED_QUOTE_REQUIRED'using errcode='55000';end if;
 client_value:=private.current_client_contract_party_v1(s.client_organization_id);provider_value:=private.provider_current_identity_snapshot_v1(v.provider_organization_id);original:=private.provider_quote_identity_snapshot_v1(v.id);address_value:=private.provider_canonical_registered_address_v1(v.provider_organization_id);
 if client_value is null then blocked:=array_append(blocked,'CLIENT_IDENTITY_REVIEW_REQUIRED');end if;
 if not private.provider_current_identity_is_verified_v1(v.provider_organization_id)then blocked:=array_append(blocked,'PROVIDER_IDENTITY_REVIEW_REQUIRED');end if;
 if not exists(select 1 from public.organizations where id=s.client_organization_id and status='ACTIVE')or not exists(select 1 from public.organizations where id=v.provider_organization_id and status='ACTIVE')then blocked:=array_append(blocked,'ACTIVE_ORGANIZATIONS_REQUIRED');end if;
 if not private.subscription_financially_clear(s.client_organization_id)then blocked:=array_append(blocked,'CLIENT_FINANCIAL_HOLD_ACTIVE');end if;
 if not coalesce((private.provider_service_eligibility_snapshot(v.provider_organization_id,s.service_id)->>'eligible')::boolean,false)then blocked:=array_append(blocked,'PROVIDER_NOT_ELIGIBLE_FOR_NEW_COMMITMENT');end if;
 provider_value:=provider_value||jsonb_build_object('schema_version',1,'organization_id',v.provider_organization_id,'verified_identity_hash',private.canonical_request_hash(provider_value),'identity_review_id',(select id from public.provider_identity_verification_history where organization_id=v.provider_organization_id order by verified_at desc,id desc limit 1),'verified_at',(select verified_at from public.provider_identity_verification_history where organization_id=v.provider_organization_id order by verified_at desc,id desc limit 1));
 basis:=jsonb_build_object('quote_version_id',v.id,'request_id',s.id,'client_organization_id',s.client_organization_id,'provider_organization_id',v.provider_organization_id,'source_quote_hash',v.content_hash,'selection_hash',private.canonical_request_hash(to_jsonb(d)),'current_client_party',client_value,'provider_party_base',provider_value,'canonical_provider_address',address_value,'previous_provider_address',original->>'registered_address');
 return basis||jsonb_build_object('context_hash',private.canonical_request_hash(basis),'blocked_reasons',to_jsonb(blocked),'original_provider_current',coalesce(original->>'verified_identity_hash'=provider_value->>'verified_identity_hash'and(address_value is null or original->>'registered_address'=address_value),false));
end$$;
revoke all on function private.selected_quote_identity_context_v1(uuid)from public,anon,authenticated,service_role;
create function private.effective_selected_quote_identity_snapshot_v1(p_quote_version_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$
declare context_value jsonb;p public.selected_quote_identity_proposals_v1%rowtype;begin
 context_value:=private.selected_quote_identity_context_v1(p_quote_version_id);
 select proposal.*into p from public.selected_quote_identity_proposals_v1 proposal join public.selected_quote_identity_responses_v1 response on response.proposal_id=proposal.id and response.decision='ACCEPT'and response.content_hash=proposal.content_hash and response.responded_by<>proposal.proposed_by where proposal.quote_version_id=p_quote_version_id and proposal.context_hash=context_value->>'context_hash'order by response.responded_at desc,proposal.id desc limit 1;
 if p.id is not null then return p.provider_party;end if;
 if(context_value->>'original_provider_current')::boolean then return private.provider_quote_identity_snapshot_v1(p_quote_version_id);end if;return null;
end$$;
revoke all on function private.effective_selected_quote_identity_snapshot_v1(uuid)from public,anon,authenticated,service_role;
notify pgrst,'reload schema';
commit;
